referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const histories = new Map(),
    out = [];
  for (const op of d) {
    if (op.op === "set") {
      if (!histories.has(op.key)) histories.set(op.key, []);
      histories.get(op.key).push([op.time, op.value]);
    } else {
      const h = histories.get(op.key) ?? [];
      let value = null;
      for (const [time, v] of h) {
        if (time <= op.time) value = v;
        else break;
      }
      out.push(value);
    }
  }
  return out;
}

