type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const histories = new Map<string, any[]>(),
    out: any[] = [];
  for (const op of d) {
    if (op.op === "set") {
      if (!histories.has(op.key)) histories.set(op.key, []);
      histories.get(op.key)!.push([op.time, op.value]);
    } else {
      const h = histories.get(op.key) ?? [];
      let value: any = null;
      for (const [time, v] of h) {
        if (time <= op.time) value = v;
        else break;
      }
      out.push(value);
    }
  }
  return out;
}
